```rust
use tokio::prelude::*;

async fn write_to_file(path: &str) -> Result<(), Box<dyn Error>> {
    let file = File::open(path)?;
    let contents = file.read_to_string()?;
    file.write(contents.into_boxed_str())?;
    Ok(())
}

async fn main() -> Result<(), Box<dyn Error>> {
    let path = "/path/to/file.txt";
    let res = write_to_file(path)?;
    Ok(res)
}
```

